def build_vocab(tokens):
    vocab = {}
    for t in tokens:
        if t not in vocab:
            vocab[t] = len(vocab)
    return vocab

tokens = ['я', 'учу', 'python', 'и', 'учу', 'sql']
vocab = build_vocab(tokens)
print(vocab)
print('в числах:', [vocab[t] for t in tokens])

# грубая модель «предскажи следующее слово» на частотах пар
text = 'я учу python я учу sql я пишу код'
words = text.split()

pairs = {}
for a, b in zip(words, words[1:]):
    pairs.setdefault(a, {})
    pairs[a][b] = pairs[a].get(b, 0) + 1

def predict(word):
    options = pairs.get(word)
    if not options:
        return None
    return max(options, key=options.get)

for w in ['я', 'учу', 'пишу']:
    print(f"после '{w}' вероятнее всего: {predict(w)}")

from math import log

docs = [
    "кот сидит на окне",
    "кот спит на диване",
    "курс доллара вырос на бирже",
]

def words(text):
    return text.lower().split()

def idf(word):
    # в скольких документах встречается слово
    n = sum(1 for d in docs if word in words(d))
    return log(len(docs) / n) if n else 0.0

for w in ["на", "кот", "биржe", "доллара"]:
    print(f"{w:10} idf = {idf(w):.3f}")

def bag(text):
    counts = {}
    for word in text.lower().split():
        counts[word] = counts.get(word, 0) + 1
    return counts

a = "собака укусила человека"
b = "человека укусила собака"

print(bag(a))
print(bag(b))
print("мешки совпадают:", bag(a) == bag(b))

def ngrams(tokens, n):
    return [tuple(tokens[i:i + n]) for i in range(len(tokens) - n + 1)]

words = "я люблю кофе я люблю чай".split()
print("биграммы:", ngrams(words, 2))

counts = {}
for pair in ngrams(words, 2):
    counts[pair] = counts.get(pair, 0) + 1

for pair, c in sorted(counts.items(), key=lambda kv: (-kv[1], kv[0])):
    print(pair, "->", c)

import math

vectors = {
    "кот":    [0.9, 0.1, 0.0],
    "кошка":  [0.8, 0.2, 0.1],
    "пёс":    [0.7, 0.3, 0.0],
    "машина": [0.0, 0.1, 0.9],
}

def cosine(a, b):
    dot = sum(x * y for x, y in zip(a, b))
    na = math.sqrt(sum(x * x for x in a))
    nb = math.sqrt(sum(y * y for y in b))
    return dot / (na * nb)

base = "кот"
for word, vec in vectors.items():
    if word == base:
        continue
    print(base, "~", word, "->", round(cosine(vectors[base], vec), 3))

